from pathlib import Path
import base64, json
R = Path(__file__).resolve().parents[2]
O = R / 'renders/secretgarden_reseau_v1'
m = json.loads((O / 'manifest.json').read_text())


def uri(p):
    return 'data:image/png;base64,' + base64.b64encode(p.read_bytes()).decode()


data = {}
for e in m['rooms']:
    d = O / e['id']
    data[e['id']] = {**e,
                     'images': {n: uri(d / (n + '.png')) for n in e['layers']},
                     'flowers': [uri(d / 'fleurs' / f'06_fleurs_f{i}.png') for i in range(4)],
                     'veg': [uri(d / 'vegetation' / f'veg_f{i}.png') for i in range(4)],
                     'schema': uri(d / 'schema.png')}
h = '''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jardin secret · réseau connectable V5</title><style>*{box-sizing:border-box}body{margin:0;background:#1d3320;color:#eef4da;font:16px system-ui}header,main,footer{max-width:1260px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#cfdcc0;line-height:1.6}.tag{font-size:12px;letter-spacing:2px;color:#b8d489}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}select,button{padding:12px;border:1px solid #6f9151;border-radius:6px;background:#33482a;color:#f4f9e8}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px}canvas{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#101a10}aside{background:#24351f;padding:18px;border-radius:8px}label{display:block;margin:12px 0;font-size:14px}a{color:#d7e8b8}small{color:#b3c49b}footer{border-top:1px solid #435c36}.anim{display:flex;gap:8px;align-items:center;margin:12px 0;font-size:14px;flex-wrap:wrap}.anim button{padding:8px 12px}#dl{margin-top:14px;font-size:13px;line-height:2}#dl b{display:block;margin-bottom:4px}@media(max-width:780px){.layout{grid-template-columns:1fr}}</style><header><div class="tag">JARDIN SECRET / RÉSEAU STYLE LEDIAN / V5</div><h1>Sept pièces connectables · 19 accès</h1><p>Sol, chemin, arbres, buissons, rochers, fleurs et bordure jungle en couches séparées. Fleurs et végétation animées en 4 phases à 200ms. Bouton « vue nue » : sol + chemin + fleurs, sans verdure ni rochers. Tilesheets et exports ci-contre.</p></header><main><div class="toolbar"><select id="room"></select><button id="plan">Voir schéma des accès</button><button id="reference">Voir référence native</button><button id="export">Exporter PNG affiché</button><button id="nue">🌱 Vue nue</button></div><div class="layout"><section><canvas id="view" width="512" height="512"></canvas><div class="anim"><button id="play">⏸ Pause anim</button><button id="step">⏭ Phase suivante</button><span id="phase">phase 0/4 · 200ms</span></div><div class="anim"><label style="margin:0"><input type="checkbox" id="vegon" checked> végétation animée</label><label style="margin:0"><input type="checkbox" id="flon" checked> fleurs animées</label></div><p id="status"></p></section><aside><b>Calques alignés · 512 × 512</b><div id="layers"></div><div id="dl"><b>Tilesheets &amp; exports</b><div id="dllinks"></div></div><small>Végétation animée = 03+04 fusionnés et balancés ; elle remplace les deux couches fixes quand activée. La bande commune garantit le sol au passage, pas l’emboîtement de toute la silhouette végétale.</small></aside></div></main><footer><p>Source : secretgarden.png + Southern_Jungle_entrance_S.png. Architectures générées guidées, pas des cartes natives originales. Animations créées pour ce lot (cadence Sky Peak), pas des cycles officiels récupérés.</p><small>19 ports de 64px : bande de 24px opaque vérifiée, fenêtres dégagées dans la bordure jungle. Ni collisions, ni transitions PMDO, ni test de navigation.</small></footer><script>const DATA=__DATA__,REF=__REF__,FLOWER='06_fleurs',VEGA='03_arbres',VEGB='04_buissons',ROOT='renders/secretgarden_reseau_v1/',c=document.getElementById('view'),ctx=c.getContext('2d'),select=document.getElementById('room');let entry,images={},flowers=[],veg=[],visible={},boxes={},schema=false,reference=false,nue=false,playing=true,fi=0,last=0;function image(src){let im=new Image();im.src=src;return im}const ref=image(REF);function download(src,name){let a=document.createElement('a');a.href=src;a.download=name;a.click()}for(const [id,e]of Object.entries(DATA)){let o=document.createElement('option');o.value=id;o.textContent=e.title;select.append(o)}select.value='salle_carrefour';const HIDE_NUE=['03_arbres','04_buissons','05_rochers','07_bordure_jungle'];function setup(){entry=DATA[select.value];images={};flowers=entry.flowers.map(image);veg=entry.veg.map(image);visible={};boxes={};fi=0;nue=false;document.getElementById('nue').textContent='🌱 Vue nue';const root=document.getElementById('layers');root.innerHTML='';for(const n of entry.layers){if(n===FLOWER)continue;images[n]=image(entry.images[n]);visible[n]=true;const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>{visible[n]=ch.checked;if(nue&&HIDE_NUE.includes(n)&&ch.checked){nue=false;document.getElementById('nue').textContent='🌱 Vue nue'}};boxes[n]=ch;a.href=entry.images[n];a.download=entry.id+'_'+n+'.png';a.textContent=' ↓';l.append(ch,document.createTextNode(n.replace(/^\\d+_/,'').replaceAll('_',' ')),a);root.append(l)}images[FLOWER]=image(entry.images[FLOWER]);visible[FLOWER]=true;const l=document.createElement('label'),ch=document.createElement('input');ch.type='checkbox';ch.checked=true;ch.onchange=()=>visible[FLOWER]=ch.checked;boxes[FLOWER]=ch;l.append(ch,document.createTextNode('fleurs animées (4 phases)'));const fl=root.children;root.insertBefore(l,fl[Math.min(6,fl.length)]);images.schema=image(entry.schema);document.getElementById('status').textContent=entry.title+' · Accès : '+entry.ports.map(p=>p.direction).join(' / ')+' · 64px';const id=entry.id,dl=document.getElementById('dllinks');dl.innerHTML='';const links=[[id+'/composition_nue.png','version nue PNG'],[id+'/composition_nue_animee.gif','version nue GIF'],[id+'/composition_full_animee.gif','GIF complet animé'],[id+'/rochers_tilesheet.png','tilesheet rochers'],[id+'/rochers_manifest.json','manifeste rochers'],[id+'/vegetation/vegetation_frames.png','végétation 4 phases'],[id+'/vegetation/buissons_spritesheet.png','spritesheet buissons'],[id+'/'+id+'.ora','projet OpenRaster']];for(const [f,t]of links){const a=document.createElement('a');a.href=ROOT+f;a.textContent=t;a.target='_blank';dl.append(a,document.createElement('br'))}}select.onchange=setup;document.getElementById('plan').onclick=e=>{schema=!schema;reference=false;e.target.textContent=schema?'Voir rendu':'Voir schéma des accès'};document.getElementById('reference').onclick=e=>{reference=!reference;e.target.textContent=reference?'Revenir à la variante':'Voir référence native'};document.getElementById('export').onclick=()=>download(c.toDataURL(),reference?'secretgarden_reference.png':entry.id+(schema?'_schema':'_f'+fi)+(nue?'_nue':'')+'.png');document.getElementById('nue').onclick=e=>{nue=!nue;e.target.textContent=nue?'🌳 Vue complète':'🌱 Vue nue';for(const n of HIDE_NUE){visible[n]=!nue;if(boxes[n])boxes[n].checked=!nue}};document.getElementById('play').onclick=e=>{playing=!playing;e.target.textContent=playing?'⏸ Pause anim':'▶ Animer'};document.getElementById('step').onclick=()=>{playing=false;document.getElementById('play').textContent='▶ Animer';fi=(fi+1)%4};function draw(im){if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}function render(t){if(playing&&t-last>200){last=t;fi=(fi+1)%4;document.getElementById('phase').textContent='phase '+fi+'/4 · 200ms'}const w=reference?408:512,h=reference?408:512;if(c.width!==w||c.height!==h){c.width=w;c.height=h}ctx.clearRect(0,0,c.width,c.height);if(reference)draw(ref);else if(schema)draw(images.schema);else{const vegOn=document.getElementById('vegon').checked,flOn=document.getElementById('flon').checked;for(const n of entry.layers){if(n===FLOWER||n===VEGA||n===VEGB)continue;if(visible[n])draw(images[n])}if(vegOn&&!nue&&(visible[VEGA]||visible[VEGB])){const v=veg[fi];if(v.complete&&v.naturalWidth)draw(v)}else{if(visible[VEGA])draw(images[VEGA]);if(visible[VEGB])draw(images[VEGB])}if(visible[FLOWER]){if(flOn){const f=flowers[fi];if(f.complete&&f.naturalWidth)draw(f);else draw(images[FLOWER])}else draw(images[FLOWER])}}requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
(R / 'apercu_jardin_secret_reseau_v1.html').write_text(
    h.replace('__DATA__', json.dumps(data)).replace('__REF__', json.dumps(uri(R / 'secretgarden.png'))),
    encoding='utf8')
print('gallery v5 written')
